css
/* 顶层容器 - 整体风格基调 */
.ctn {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: #e0e0e0;
  font-family: 'Microsoft YaHei', 'SimHei', sans-serif;
  border: 2px solid #0f3460;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6), inset 0 0 20px rgba(15, 52, 96, 0.2);
  max-width: 800px;
  margin: 20px auto;
  line-height: 1.6;
}

/* 头部信息栏 */
.header-info {
  background: rgba(15, 52, 96, 0.3);
  border-left: 4px solid #00d4ff;
  padding: 12px 16px;
  margin-bottom: 16px;
  border-radius: 8px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.info-item {
  font-size: 14px;
}

.info-item .label {
  color: #00d4ff;
  font-weight: bold;
  margin-right: 6px;
}

.info-item .value {
  color: #f0f0f0;
}

/* 正文区域 */
.main-body {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(0, 212, 255, 0.3);
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 16px;
  font-size: 15px;
  min-height: 80px;
}

/* 折叠栏通用样式 */
details {
  margin-bottom: 14px;
  border: 1px solid rgba(0, 212, 255, 0.4);
  border-radius: 8px;
  background: rgba(15, 52, 96, 0.2);
  overflow: hidden;
}

summary {
  cursor: pointer;
  padding: 12px 16px;
  font-weight: bold;
  font-size: 16px;
  color: #00d4ff;
  background: rgba(0, 212, 255, 0.1);
  border-bottom: 1px solid transparent;
  transition: all 0.3s ease;
}

summary:hover {
  background: rgba(0, 212, 255, 0.2);
  box-shadow: inset 0 0 10px rgba(0, 212, 255, 0.3);
}

summary::-webkit-details-marker {
  display: none;
}

summary::before {
  content: '[+] ';
  color: #00ff88;
  font-weight: bold;
  margin-right: 8px;
}

details[open] > summary::before {
  content: '[-] ';
}

details[open] > summary {
  border-bottom-color: rgba(0, 212, 255, 0.4);
}

/* 信息网格 */
.info-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 12px 16px;
  padding: 16px;
  align-items: center;
}

.grid-label {
  color: #00d4ff;
  font-weight: bold;
  font-size: 14px;
}

.grid-value {
  color: #f0f0f0;
  font-size: 14px;
}

/* 进度条 - 外边框容器 */
.progress-bar {
  border: 2px solid #0f3460;
  background-color: rgba(0, 0, 0, 0.4);
  border-radius: 10px;
  overflow: hidden;
  height: 20px;
  position: relative;
}

.progress-bar.small {
  height: 16px;
  border-radius: 8px;
}

/* 进度条 - 内填充 */
.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #00ff88 0%, #00d4ff 100%);
  border-radius: 8px;
  transition: width 0.4s ease;
  box-shadow: 0 0 10px rgba(0, 255, 136, 0.6);
}

.progress-fill.energy {
  background: linear-gradient(90deg, #ffd700 0%, #ff8c00 100%);
  box-shadow: 0 0 10px rgba(255, 215, 0, 0.6);
}

/* 窥欲值专用样式 */
.progress-fill.voyeurism {
  background: linear-gradient(90deg, #ff8c00 0%, #ff4500 100%);
  box-shadow: 0 0 10px rgba(255, 140, 0, 0.8);
}

/* 堕落值专用样式 */
.progress-fill.corruption {
  background: linear-gradient(90deg, #ff6b6b 0%, #ff0000 100%);
  box-shadow: 0 0 10px rgba(255, 107, 107, 0.8);
}

/* 改造度专用样式 */
.progress-fill.modification {
  background: linear-gradient(90deg, #9b59b6 0%, #8e44ad 100%);
  box-shadow: 0 0 10px rgba(155, 89, 182, 0.8);
}

/* 伴侣状态栏 */
.partner-section {
  border-color: rgba(255, 107, 107, 0.4);
  background: rgba(155, 89, 182, 0.1);
}

.partner-grid {
  padding: 16px;
}

.partner-basic {
  display: flex;
  align-items: center;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255, 107, 107, 0.3);
}

.partner-avatar {
  font-size: 32px;
  margin-right: 12px;
}

.partner-info {
  flex: 1;
}

.partner-name {
  color: #ff6b6b;
  font-weight: bold;
  font-size: 18px;
  margin-bottom: 4px;
}

.partner-detail {
  color: #e0e0e0;
  font-size: 13px;
}

.partner-stats {
  margin-bottom: 16px;
}

.stat-item {
  display: flex;
  align-items: center;
  margin-bottom: 12px;
}

.stat-item:last-child {
  margin-bottom: 0;
}

.stat-label {
  color: #ff6b6b;
  font-weight: bold;
  width: 60px;
  font-size: 13px;
}

.stat-value {
  color: #f0f0f0;
  font-size: 12px;
  margin-left: 8px;
  min-width: 40px;
}

.personality-stage {
  margin-bottom: 16px;
  padding: 12px;
  background: rgba(255, 107, 107, 0.1);
  border-radius: 6px;
}

.stage-label {
  color: #9b59b6;
  font-weight: bold;
  font-size: 14px;
  margin-bottom: 6px;
}

.stage-value {
  color: #00ff88;
  font-size: 14px;
  font-weight: bold;
}

.modification-list {
  background: rgba(0, 0, 0, 0.2);
  border-radius: 6px;
  padding: 12px;
}

.list-label {
  color: #9b59b6;
  font-weight: bold;
  font-size: 14px;
  margin-bottom: 8px;
}

.list-content {
  color: #e0e0e0;
  font-size: 13px;
  line-height: 1.5;
}

/* 记忆容器 */
.memory-container {
  padding: 16px;
}

.memory-category {
  margin-bottom: 16px;
}

.memory-category:last-child {
  margin-bottom: 0;
}

.category-title {
  color: #00ff88;
  font-weight: bold;
  font-size: 15px;
  margin-bottom: 8px;
  border-bottom: 1px solid rgba(0, 255, 136, 0.3);
  padding-bottom: 4px;
}

.memory-list {
  background: rgba(0, 0, 0, 0.2);
  border-radius: 6px;
  padding: 12px;
  max-height: 150px;
  overflow-y: auto;
}

.memory-list.long-term {
  background: rgba(15, 52, 96, 0.2);
  border: 1px solid rgba(0, 212, 255, 0.2);
}

.memory-entry {
  display: flex;
  align-items: flex-start;
  margin-bottom: 8px;
  font-size: 13px;
  line-height: 1.5;
}

.memory-entry:last-child {
  margin-bottom: 0;
}

.memory-number {
  color: #ffd700;
  font-weight: bold;
  margin-right: 8px;
  flex-shrink: 0;
}

.memory-content {
  color: #e0e0e0;
  word-break: break-all;
}

/* 滚动条美化 */
.memory-list::-webkit-scrollbar {
  width: 6px;
}

.memory-list::-webkit-scrollbar-track {
  background: rgba(15, 52, 96, 0.3);
  border-radius: 3px;
}

.memory-list::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #00ff88 0%, #0f3460 100%);
  border-radius: 3px;
  border: 1px solid rgba(0, 255, 136, 0.5);
}

.memory-list::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, #00d4ff 0%, #00ff88 100%);
}

/* 行动选项区域 */
.actions-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 16px;
}

.action-option {
  border: 2px solid #0f3460;
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.1) 0%, rgba(15, 52, 96, 0.2) 100%);
  padding: 14px 18px;
  border-radius: 8px;
  font-size: 15px;
  cursor: pointer;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.action-option::before {
  content: '▶ ';
  color: #00ff88;
  font-weight: bold;
  margin-right: 8px;
}

.action-option:hover {
  background: linear-gradient(135deg, rgba(0, 255, 136, 0.2) 0%, rgba(0, 212, 255, 0.3) 100%);
  border-color: #00d4ff;
  box-shadow: 0 0 20px rgba(0, 212, 255, 0.5), inset 0 0 15px rgba(0, 255, 136, 0.2);
  transform: translateY(-2px);
}

/* 响应式设计 */
@media (max-width: 768px) {
  .ctn {
    padding: 16px;
    margin: 10px;
  }

  .header-info {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .info-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .grid-label {
    margin-bottom: -8px;
  }

  summary {
    font-size: 15px;
    padding: 10px 14px;
  }

  .main-body {
    font-size: 14px;
    padding: 14px;
  }

  .memory-container {
    padding: 12px;
  }

  .memory-list {
    max-height: 120px;
  }

  .partner-basic {
    flex-direction: column;
    text-align: center;
  }

  .partner-avatar {
    margin-right: 0;
    margin-bottom: 8px;
  }
}
